  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (221::BIGINT, 'gracias por contribuir a que me cambiara de carrera al entender que la ingeniería física no es para mí dado que mis habilidades e intelecto no están a su altura.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-26T00:00:00+00:00'::TIMESTAMPTZ, '6e96f1cfad6dde52eb4841a54de7642c2501c4c6c007a2be700cf998334dc0cc'::TEXT, ARRAY[1369]::BIGINT[]),
    (221::BIGINT, 'El mae chill. Definitivamente no es apasionado, pero explica muy claro y ayuda mucho, hace los labs fáciles y rápidos, califica muy bien. Vi que decían que amargado y humilla, pero personalmente no vi ningún comportamiento así, me cayó normal/bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '6fc538a689ceaf487824ec53fe7c60574838de45a67e8b82a1e650d241245408'::TEXT, ARRAY[631]::BIGINT[]),
    (221::BIGINT, 'Es un toq amargado, pero es buen profe dentro de lo que cabe. Si lo puede llegar a humillar a uno si estás perdido. Los reportes los califica suave pero los informes y quices si califica duro. Creo que hay mejores opciones pero si le tocó, no está mal. Lo bueno es q es liguista JAJA'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2025-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ea02d636f79ae50b3f7bfe9c8ad0fd29a03d965041d479fcec31cc18b8ba7f10'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Muy buen profe en general, califica suave a mi parecer, las clases son cortas y explica bien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'ee8f9bcf18a9f5960a6a0ffead07886692096b224f8a1c70e437648fd8013a9c'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'El profe es un poco amargado pero explica bien y se nota que sabe. Los reportes los califica suave pero en los informes si se vuela un toque.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'e2472d6ef4a6cc2e73e8e4a0c6c6d895a85a79ecd6ad898825597635c06b5b68'::TEXT, ARRAY[631]::BIGINT[]),
    (221::BIGINT, 'Profesor sumamente pedante, suele menospreciarlo a uno por errores mínimos, con frases como: "Quién fue su prfoesor de física 1", lo último con mucho desprecio. Aunque su nivel de salvajismo lo incentiva a uno a estudiar y prepararse más.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '1e832309646391192aa11996e85f662864a5112eabde9a56583165dcdddc431c'::TEXT, ARRAY[631]::BIGINT[]),
    (221::BIGINT, 'El mae es buen profe. Claro un poco amargado. A pesar de que era lab si uno tenía dudas para FG1 teoría el mae ayuda. Hay que ir a clases porque son obligatorias.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '0275dddf6572595e30196f5496560a3ccafbc2e16ae16a0e910d2f8b3ce6d954'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Debo admitirlo, este profe me motivo a leer mas sobre conducta humana, es sumamente pedante y extraño, siempre he pensado que asi son la mayoria de fisicos, pero este..es raro de verdad...no pierda el tiempo, hay otras opciones, este tipo debe trabajar mucho la parte social o trabajar en otra cosa.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2024-10-29T00:00:00+00:00'::TIMESTAMPTZ, 'd585c4681dff96cf489a61841a0f0dd906aeba2eece3ad9d5ddf1faf1f124a24'::TEXT, ARRAY[922]::BIGINT[]),
    (221::BIGINT, 'Creo que no va a volver a dar el curso, podrá saber mucho, pero es un profesor demasiado pedante. No ayuda al estudiante y lo trata a uno como idiota y que todo es muy obvio. De verdad que no genera nada de confianza ese profesor. No facilita otros recursos, todo es en pizarra.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'b9da67afee767937a6f66fb519e6a5dc5d2c375f571d69692ebdf561c9b37f9a'::TEXT, ARRAY[922]::BIGINT[]),
    (221::BIGINT, '(2/2)Miras el cel por 5 minutos y ya se habrá hecho 2 pizarras de materia, Quizes presenciales y en el examen corrige DURO, errores mínimos te pueden costar la mitad del problema, no recomiendo llevar por primera vez si te cuesta derivar/integrar o la física en si'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2024-05-26T00:00:00+00:00'::TIMESTAMPTZ, '9adeb2dc8497929c5dd63cd9905706947f5edf1cd3d062ff16256100d9cf12b1'::TEXT, ARRAY[922]::BIGINT[]),
    (221::BIGINT, 'El profe sabe UN MONTÓN de la materia y para ser la primera vez que da el Curso y con las nuevas evaluaciones que puso la cátedra haciendo el curso más dificil que fisica 2, no lo hizo tan mal, sin embargo en las clases van a tener que vivir con el lápiz en la mano (1/2)'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2024-05-20T00:00:00+00:00'::TIMESTAMPTZ, '81babb0117cec2583953b4a4f45e2b76839d2460e0f127643319d022e40368ad'::TEXT, ARRAY[922]::BIGINT[]),
    (221::BIGINT, 'Para Física 2 podría ser el mejor profesor. Explica bien, los ejercicios que se explican en clase son más complicados que los de los exámenes. Hay que tomar en cuenta que en ocasiones uno se puede perder en la clase por copiar todo lo que escribe el profe.En la mayoría de los casos califica bien.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-22T00:00:00+00:00'::TIMESTAMPTZ, '66ce18e29a5dc9ef6e4b5c344da9f9e7c3c24787e994f08b0b72d37c028b4eae'::TEXT, ARRAY[630]::BIGINT[]),
    (221::BIGINT, 'Excelente profesor, hace buenas explicaciones y pone ejemplos nivel examen, por lo que los mismos abarcan buen contenido y dudas. Califica súmamente bien. Es bastante relajado y gracioso, excepto cuando está de mal humor. Vaya con él, es una buena forma para pasar si lleva el curso por primera vez.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'eb6c9068d88df81763d3a471a7b539d356af707818697196d3680192376e6d95'::TEXT, ARRAY[630]::BIGINT[]),
    (221::BIGINT, 'El curso es complejo pero el profe lo ayuda a pasar a uno. El profe quices hace muy sencillos y si quiere física pasar física a la primera, llevarlo con él es la mejor opción'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-10-26T00:00:00+00:00'::TIMESTAMPTZ, 'a9b44bd611c21581373e37d6d01f66a879853f76b24b11f9748f6bb04949a0ca'::TEXT, ARRAY[630]::BIGINT[]),
    (221::BIGINT, 'Es uno de los mejores profes que he tenido. El profesor, aunque un poco serio, daba los temas de forma sencilla y eso que los temas son complejos. Hace ejercicios que lo preparan a uno para el examen y hace quices con preguntas de teoría que son de gran ayuda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'ad8f2b381d34323649de9ac7709af2816bdb9fa10667516bc059a763a603a46b'::TEXT, ARRAY[630]::BIGINT[]),
    (221::BIGINT, 'Es buen profesor y se ve que sabe lo que está enseñando. Eso sí es un poco tosco a veces. El curso no es para nada sencillo pero el profe explica cada paso de los problemas que hace en la pizarra. Todas las evaluaciones del curso tienen solución que el mismo profe da lo cual es de gran ayuda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9cccc266e52ea126ec2803bad09b945558705c3ea7f01380db57b6575ea8d80e'::TEXT, ARRAY[4128]::BIGINT[]),
    (221::BIGINT, 'El profe es bueno explicando, pero está de mal humor la mayoría del tiempo, por lo que existe cierta tensión en la clase. El profe no es nada empático, pero aún así dejó bastante claro los temas del curso.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '237ad65f8bdaa4576f69a0b9894bd980861f928973265781c92bf3ec6a11b9b8'::TEXT, ARRAY[4128]::BIGINT[]),
    (221::BIGINT, 'Es bueno como profesor, quices presenciales nivel examen el dia antes del examen, entonces ese 10% de otras evaluaciones que poneel profesor lo va a tener que pelear, explica bien, buena nota para calificar, busca ayudar donde puede al calificar. Muy tosco para hablar, pero en realidad es buena nota'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'b90c99889fae177421677cd19deabdc74e6eae6346d87bc058db3101da9f0c69'::TEXT, ARRAY[630]::BIGINT[]),
    (221::BIGINT, 'NO volvería a matricular con él. Es tosco, nunca contesta las consultas, la ayuda parece más un cuestionamiento que una retroalimentación, trabaja con rúbricas pero parece que califica según lo vea adecuado,deja comentarios vagos, no se sabe en qué se equivocó. Si no es autodidacta le va a ir muymal'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '2e6654d882f32ea06313708322e560463435115eacafc1f7ac3d6193c9fb949e'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Las clases son geniales, el profe ayuda en donde puede. El curso es BASTANTE difícil, no es suficiente con lo que se ve en clase, hay que practicar mucho y ampliar conceptos por aparte. Suerte, la va a ocupar...'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'f2d27f91f2ee5334a3c0af2e00989b73e5a106c720f99c28216f4ed33d3a43c7'::TEXT, ARRAY[4125]::BIGINT[]),
    (221::BIGINT, 'El profe es demasiado bueno dando el curso, lo ayuda a uno con la nota de los exámenes, y rescata puntos de donde se puede. Eso sí, el curso es bastante complicado y debe dominar muy bien Ecuaciones diferenciales, álgebra lineal y superior para poder pasar el curso.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-24T00:00:00+00:00'::TIMESTAMPTZ, '1ab5fbddd3f9c59b3752db852540adeba83ec62b8a521157f15fdb29a6a565fc'::TEXT, ARRAY[4125]::BIGINT[]),
    (221::BIGINT, 'Legal me guie por mis profes TEC y es una mierda de profe, no volvería a matricular con el nunca, no le crean a los comentarios que habían'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-11-15T00:00:00+00:00'::TIMESTAMPTZ, '70a28fb711625ca581a98623aa1d77040adb489e8e52534fb0154d83cc2ad495'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Excelente profesor, un tanto cómico, siempre se queja de cosas que le molestan pero al final se lo toma de buen humor, se aprende bien y es un profe tranquilo, lo que si tiene es que los informes los califica a matar, pero el explica muy bien como deben de ir estructurados'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '1db71a1664048639b27ea9518ec955686f37095c4290e162ed3cfba2b0c20405'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'La verdad es una teja y domina los temos que enseña como pocos profes los dominan. Parece que se enoja por las preguntas pero es vara. Uno se pasa cagando de risa con lo que dice en clase y en telegram. Ayuda bastante y las tareas ayudan demasiado para el examen.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'f68e2e58d0e75b2cc4d305f5e81352d1986f1efa3f0b523346e1281dbe8490c0'::TEXT, ARRAY[607, 4128]::BIGINT[]),
    (221::BIGINT, 'Es una teja de mae y de profe, se nota que domina los temas y explica muy bien. Ayuda demasiado en consulta, suena como que se enoja con las dudas pero en realidad no es así. Las tareas pueden ser largas y rudas pero a uno lo deja listo para el examen si uno las hace a conciencia.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2022-02-14T00:00:00+00:00'::TIMESTAMPTZ, 'ef850fedf6540bcc3424b39ec955d3a323e6ab992929e93c6e1feca7d1407e63'::TEXT, ARRAY[607, 4128]::BIGINT[]),
    (221::BIGINT, 'Es muy bueno, maneja los temas muy bien, solo que a veces puede perder un poco la paz con las preguntas. Las tareas son largas, pero regularmente las reutiliza de exámenes y tareas pasadas. Los exámenes son duros, pero si hace las tareas y va a clase, sale bien. Los quices son retadores, pero salen.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '6477a83f6743cf10e8e4665401b6e26eaabb3063202d7f79d607068a0a4c660f'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Es un gran profesor, explica muy simple pero abarcando todo lo necesario para realizar todos los trabajos, eso si se enoja si uno no ha leído el material antes de la clase....'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'c0652c10172a1d8d70015c18a6d47ca2db8a14264204e614fb152e9ad87a135e'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Escuchó las observaciones del primer curso y lo corrigió para el segundo. El profesor sabe mucho de los temas y es super ordenado con las evaluaciones y da buena retroalimentación. El curso en sí es difícil pero los ejemplos de clase son del mismo nivel o superior alos de las tareas y exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'b52deb31260d175b1f619f5a3ba80ece4275bfd33457d9e3f2d8b9ff3f97062f'::TEXT, ARRAY[4128]::BIGINT[]),
    (221::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '8058869881a815774bebfc88090dc67f2c0c71823120fc36681b062cca47323f'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'El profe sabe mucho de los temas del laboratorio. Si uno no entiende algo en consulta tiene la paciencia de verlo de nuevo. Califica justo los informes y usa heteroevaluación lo que hace más justo todo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'e316720f5d70c0981ac794852b6387ce800447dc1104144495bda58f6141c387'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Una mejora sustancial respecto al curso anterior. Se nota que intenta mejorar.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, '15d2f0cd5327728ca43d767b2e9fae9cc9420056bec57dd22d2f3dafeebe39e1'::TEXT, ARRAY[4128]::BIGINT[]),
    (221::BIGINT, 'A veces no explica todo lo que hace en la clase y le falta cierta formalidad matemática, pero ha mejorado muchísimo respecto al Métodos I, se ha vuelto bastante comprensivo y ha mejorado las evaluaciones'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '986038bc2e203459c13c53c2f790ec90da2e0e94d63b00197891f4c113ba4154'::TEXT, ARRAY[4128]::BIGINT[]),
    (221::BIGINT, 'Es buen profe, pero es muy tosco para hablar y a la hora de aclarar dudas es muy difícil contactarle pues cuesta que conteste el correo y solo se conecta a consulta a veces. Es un curso muy pesado y a veces uno necesita un profe más atento a responder por mensaje entonces para este curso no'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'd12e8d046a9f4a3432c92bb601c2c3fc961e09cf07d56c637733b98bbc257bd8'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Excelente profesor, explica super claro y si tiene que repetir, repite. Es un poco tosco a la hora de responder, pero en general siempre responde y es muy accesible en consulta. El curso es durísimo asi que preparese, sepa que si pierde el curso es culpa suya y no del profe'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'b475ec1740da33ddc5d04a8be92effc7423d1c6c29cd7127911ea09e6f005698'::TEXT, ARRAY[4125]::BIGINT[]),
    (221::BIGINT, 'El mae es un poco tosco, sin embargo, explica muy bien. Los exámenes son absurdamente largos.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '2dbef46d31014f701e0b989e317550e1eb9103d7213927e54339fb13f4a9b5cc'::TEXT, ARRAY[4125]::BIGINT[]),
    (221::BIGINT, 'Hace el curso demasiado complicado. Los exámenes son mucho más difíciles que los problemas que se hacen en clase y son muy largos. Tareas muy largas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'ffe134a8c89e46a4aad7a2126f41b0b06d38d2838f4b050d35719358de6bd388'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'En general el profe sabe mucho de la materia y se aprende bastante, pero si es un curso que los exámenes y tareas son muy difíciles y largos. El curso en si es difícil, aunque el profe explica bastante bien. El si es accesible solo que tiene su carácter y hay que saber como pedirle ayuda.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '9371b9e3eb20b8ba4e23c71d1f574216bd64a05cc5d8ef66fc09397b33983cff'::TEXT, ARRAY[4125]::BIGINT[]),
    (221::BIGINT, 'Tiene cara de amargado pero califica bien. Tuvimos un problema con un miembro de equipo y lo resolvió de buena forma. Terminó sin afetarnos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '4b25fcda175c7fa50b72c3152472ca16ec21b67da7f23a8a4a7f236f953b02d8'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Es bastante antipático y si uno tiene dudas, le explica de mala gana.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3037b2cddc465d75e2bd1aa4a57137b4826352b00b197492e7f7dad53ac6fe8a'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Explica bien la materia, pero los exámenes y tareas son muy difíciles porque evalúa cosas que nunca se vieron en el curso a un nivel mucho más alto, califica los exámenes como le da gana y baja puntos porque sí . Si uno le comenta algo que no le parece del curso se pone como un niño todo malcriado'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '94b8667566b984b1237ced6d375181a2e40d9032e2a700c037adddeb1bd30592'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'El profe es pura vida y siempre ayuda en consulta. Califica justo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-01-18T00:00:00+00:00'::TIMESTAMPTZ, '882e75636d8ca534928d405b8716c5f88823a8fcdff7e7402ce515566a5148bf'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'La modalidad virtual de laboratotio dependía demasiado de uno pero el profe siempre dió consulta por zoom en dos franjas diferentes de horas. Respondía claro a lo que se le preguntaba. Calificó duro pero justo porque usa una heteroevaluación donde uno califica a los otros.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '6a9c6cf5d156c7d0a86d73319fd736f0c8832c9ebd8293fe19cebdd3ba04a7bd'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'El profe es súper arrogante y cuando uno le pregunta muchas veces lo hace sentir todo mal. El curso virtual es 100% autodidacta, y no explica porque es deber de uno aprenderlo. Ademas, califica rudo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'da496224241e8ba3b99000cf4c44136b2481bc21afc66c364078b84375ee7e78'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Es muy arrogante y repugnante, no le gusta dar su clase y si uno no entendía se enojaba. En las consultas es super odioso y hace que uno se sienta mal al hacerle consultas'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '9b944e8f2c0f3faff11d8f5502f94b3ef1926ffa5c1ec428d9bdb9cd31dc5b7c'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'No es el más amable de los profes pero presencial explicaba claro, virtual casi no hubo interacción con él más que la consulta. Los trabajos los califica bastante duro.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '5ab7e59cb6e63b8297877441391a30f429e6743c3ec27c2782444d66605aca66'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Excelente profesor, antes de los exámenes es importante ir a consulta. Además hay que tener cuidado en los informes y exámenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '61636f3a7e221c203f4ae8afa85808688baedd4b9e5ee40babda0be89fb37f67'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Es súper pura vida. Explica bien y en consulta ayuda un montón. No califica tan duro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '8275c7b629564ab1632e51fd059b2cf784ca0eed2f049e7647e2479dd10c77cf'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Es un cagadón de risa, se hace super amena la clase. Hay que ser muy cuidadoso en los informes y experiencias, porque sino si baja puntos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '13173687256a474996deafb436e7074af57cd65aa24819290b7cbe582ab2a6a0'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Puede calificar duro pero explica súper bien. Hace el intento de que uno aprenda y no se aburra. Es importante ir a consulta antes de los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2018-12-27T00:00:00+00:00'::TIMESTAMPTZ, 'd40a95c6dde7e6d7218e8baf7a33d28ee989cacd411e7125849062adca7c22d1'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Una teja de profe, ayuda bastante y es super accesible. Es muy cómico y califica justamente. Hay que ir a consulta antes de los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '9bcdecad44ae02b3ac2ec237ebb61040fd6184aa9f235c20ec7715f31d601946'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '5cb11e03d003f6edfec1c20fc556744fe023001806500029c22c6f2e5d780963'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Buen profe, trata de hacer un buen ambiente. Casi no hace quices, pero califica fuerte. Parece un poco amargado y mala nota aveces pero al final es buena gente.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '6697a22951d2760cdc0c4732c457a78e404ea30ec1bdfa54f521f41c5e767ab4'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'El profe explica bien y hace la clase entretenida. Califica bastante duro.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '3d4e6f5dc01842e61f1d5301bf50e37f005b6d37047dae5c7f2362d64b829166'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Buen profe, hace quices antes de los exámenes. Es bueno explicando. Y comprensivo. Ayuda si le pones.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '97c8f13d2e05ae5837843fa33335f17d23015ce537e1d42aa3da9f3b7d0fdecc'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Muy buen profe, super recomendado. No califica duro, si hace quices rudos pero ayuda bastante para los examenes. Explica muy claro'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '55af58677b11effbbc54002c4e9f04613d5088b6f6e7dda3e0bb71b9f5d03b24'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Explica muy bien, y las veces que sea necesario, no califica muy duro. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f003840ac2dc78ce0f19856bc3e360005308b0d2a18cf9caf733223aa6f05ea5'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Si logra matricular con él y que no se lo cambien le va a ir bien en el curso, ya que explica de manera clara y hace bastantes ejemplos en clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2018-04-08T00:00:00+00:00'::TIMESTAMPTZ, 'df090291acbd4598897652dc9a42270348a0beb6a2ed389853469b00df1385cc'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Excelente, lleva un ritmo relajado en su clase pero avanza como debe, califica justo y es super buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '5b5aeb2717c7679cbb61c3d0f300c517df095b4dfe693d07a1da093e17981cf1'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Muy buen profe,recomendado! La materia no es facil y uno tiene que ponerle pero él siempre hace bastantes ejemplos que son complicados entonces lo ayuda a uno mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'ce3cb0723c3a469bc72e0327adaf6d56e0770c15adcd558b5fa052368d0385fb'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'IT''S A TRAP'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-11T00:00:00+00:00'::TIMESTAMPTZ, '41770185080eff47b2237baf86143875f120f5646d976e9d1d13379aa88e6638'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (221::BIGINT, 'Es una trampa siempre lo cambian... ;('::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-04-01T00:00:00+00:00'::TIMESTAMPTZ, 'e2869d376cbc39b0d8fb304469178fe000e4e62ac0c5308cd36dee77f68e973e'::TEXT, ARRAY[922, 630, 1369]::BIGINT[]),
    (221::BIGINT, 'Explica muy bien, es bastante serio, pero es muy pura vida, ayuda al final si uno le pone durante el semestre, y califica con lastima si todo el grupo sale mal.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-16T00:00:00+00:00'::TIMESTAMPTZ, '88cf7155bd50bc18012b5d2dc20ac031edb0874c35bc248056e286ae6ac91a49'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (221::BIGINT, 'Explica muy bien la materia, es un curso muy duro pero se da a entender con todo. Muy recomendado. Lo único es que en ocasiones puede ser pedante.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f44db1985ce01f08c1b2829c959ee7edd1072e16b6b3f2559cc75a393d83461d'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (221::BIGINT, 'Demasiado buen profe, llevé la salvaje fisica 2 con el y aunque me costó un mundo el man explica como un dios.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, '91fb444acc4a910680ca0b3f6a81cac9c69c1cd263573073a3bf0a340f5912d4'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (221::BIGINT, 'Es muy buen profesor, Califica normal y explica super! Lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-17T00:00:00+00:00'::TIMESTAMPTZ, '564502b3c34f70acce01851f41445c0a818ce1f908429fe27d1d84405506ed48'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Muy buen profe, explica muy bien y atiende la dudas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-23T00:00:00+00:00'::TIMESTAMPTZ, '2800d89fc7c0118ca085cb563d1f07839924819ff710c398ff2008acf881f318'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Excelente profe, muy pura vida, califica decente y explica bastante bien. No duerme en la clase y va directo al grano. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'dbf1261a788baffa63ede5865c5c75b69443a2313e790798bb006c87a2e1ed08'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Justo a la hora de calificar, es buena gente y explica muy bien, en general es un muy buen profesor.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'f7df31795a73775b862718a16938aeb80d93256898ac531cf961ad589abe5192'::TEXT, ARRAY[1369]::BIGINT[]),
    (221::BIGINT, 'Excelente profesor, explica todo de manera clara y sin rodeos. Califica normal y toma en cuenta cada evaluación que haga en el promedio final. Muy recomendado para verano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-07T00:00:00+00:00'::TIMESTAMPTZ, '9003a76d4daecb3d21230ed017dde9312b08ba1433ed60443b5abe41a79e2544'::TEXT, ARRAY[607]::BIGINT[]),
    (221::BIGINT, 'Excelente profesor, tiene buen sentido del humor y explica muy bien :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'bde399504fd9604eefd9c4953e136e41466f0b8b9f2f7d1f5473da54006687c7'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (221::BIGINT, 'A veces es un toque vago para dar la clase, sin mucho esmero, y eso se le pasa a uno. Pero caifica muy justo, cada punto que uno se gana se lo da.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ba7ec3a4b26b43f748bfe8934e075fa02d985f4febb72dc813fa62404fcab6d3'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (221::BIGINT, 'Excelente profesor, explica con claridad, ejemplos útiles y muy buena comunicación con el estudiantado7. Definitivamente una buena opción para aprender Física y pasar el curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, '2fefa6ab3b47f00361ef8e1828034026b082fb9c785aee68871a30ad2887efc1'::TEXT, ARRAY[630]::BIGINT[]),
    (221::BIGINT, 'Es muy buen profesor, cuando hace ejemplos se preocupa por que el alumno entienda. Hace ejemplos difíciles tipo examen en clase. Es muy pura vida. Sin embargo no regala las notas, es justo a la hora de calificar, quien diga lo contrario es porque le gustan las cosas regaladas. Recomendado!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'cf3b4eede7d05ec8a938d30a199a5daab1b9decfb7f1c65d776085574c0b2e12'::TEXT, ARRAY[630]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
